package main

import (
	"fmt"

	"gopkg.in/yaml.v3"
)

func probe(label, raw string) {
	var doc yaml.Node
	err := yaml.Unmarshal([]byte(raw), &doc)
	kind := "none"
	if err == nil && len(doc.Content) > 0 {
		kind = fmt.Sprintf("%v", doc.Content[0].Kind == yaml.MappingNode)
	}
	fmt.Printf("%-24s err=%v rootIsMapping=%s\n", label, err, kind)
}

func main() {
	probe("frontmatter-md", "---\nname: code-reviewer\ndescription: does things\n---\n\n# Code Reviewer\n\nYou review code.\n")
	probe("frontmatter-md-colon", "---\nname: x\n---\n\nBody with: a colon and - dash\n")
	probe("flow-mapping", "{name: x, description: y}\n")
	probe("plain-md", "# Talent\n\nbody\n")
}

